  disc:[
    ['🎈', t('Kengayuvchi koinot va qizil siljish','Расширяющаяся Вселенная и красное смещение','The expanding universe and redshift'),
      t('Galaktikalar qizil siljishini ularning fazoda harakati emas, balki fazoning o‘zi kengayishi natijasi deb tushuntirdi. Bu talqin zamonaviy kosmologiyaning asosidir.','Объяснил красное смещение галактик не их движением в пространстве, а расширением самого пространства. Эта трактовка лежит в основе современной космологии.','He explained the redshift of galaxies not as motion through space but as the expansion of space itself — the interpretation at the heart of modern cosmology.')],
    ['📈', t('Tezlik — masofa bog‘lanishi','Связь скорость — расстояние','The velocity–distance relation'),
      t('1927-yilda Xabbldan ikki yil oldin galaktikalarning uzoqlashish tezligi masofaga proporsional bo‘lishi kerakligini nazariy chiqardi va koeffitsiyentni baholadi.','В 1927 году, за два года до Хаббла, теоретически вывел, что скорость удаления галактик должна быть пропорциональна расстоянию, и оценил коэффициент.','In 1927, two years before Hubble, he derived theoretically that galaxies’ recession velocities should be proportional to distance and estimated the coefficient.')],
    ['💥', t('«Birlamchi atom» — Katta portlash g‘oyasi','«Первичный атом» — идея Большого взрыва','The “primeval atom” — the Big Bang idea'),
      t('Kengayishni vaqtda orqaga «aylantirib», koinot juda zich va issiq holatdan boshlangan bo‘lishi kerak degan xulosaga keldi. Bu g‘oya kosmik fon nurlanishi kashf etilgach (1965) keng tan olindi.','«Прокрутив» расширение назад во времени, пришёл к выводу, что Вселенная должна была начаться из очень плотного и горячего состояния. Идея получила широкое признание после открытия реликтового излучения (1965).','By “running” the expansion backwards in time, he concluded that the universe must have begun from a very dense, hot state. The idea gained wide acceptance after the discovery of the cosmic background radiation (1965).')],
    ['🧮', t('Eddington — Lemetr modeli','Модель Эддингтона — Леметра','The Eddington–Lemaître model'),
      t('Eynshteynning statik koinotidan asta-sekin kengayishga o‘tuvchi model taklif qildi; kosmologik doimiy rolini ham chuqur o‘rgandi.','Предложил модель, переходящую от статической Вселенной Эйнштейна к постепенному расширению; глубоко изучил и роль космологической постоянной.','He proposed a model that passes from Einstein’s static universe to gradual expansion, and studied the role of the cosmological constant in depth.')]
  ],
  instr:[],
  formulas:[
    { f:'1 + z = a_{0} / a_{e}', name:t('Kosmologik qizil siljish','Космологическое красное смещение','Cosmological redshift'),
      expl:t('Lemetr talqiniga ko‘ra, yorug‘lik galaktikadan chiqqan paytdan (a_{e}) bizga yetib kelguncha (a_{0}) fazo necha marta cho‘zilgan bo‘lsa, to‘lqin uzunligi ham shuncha marta cho‘ziladi. Demak, qizil siljish koinotning kengayish darajasini bevosita o‘lchaydi.','Согласно трактовке Леметра, во сколько раз растянулось пространство с момента излучения света галактикой (a_{e}) до его прихода к нам (a_{0}), во столько же раз растягивается длина волны. Значит, красное смещение напрямую измеряет степень расширения Вселенной.','In Lemaître’s interpretation, the wavelength of light is stretched by the same factor as space has expanded between emission (a_{e}) and arrival (a_{0}). Redshift therefore directly measures how much the universe has expanded.'),
      vars:[ ['z', t('qizil siljish','красное смещение','redshift')], ['a_{0}', t('hozirgi masshtab omili','современный масштабный фактор','present scale factor')], ['a_{e}', t('nur chiqqan paytdagi masshtab omili','масштабный фактор в момент излучения','scale factor at emission')] ] },
    { f:'v = H_{0} · d', name:t('Xabbl — Lemetr qonuni','Закон Хаббла — Леметра','The Hubble–Lemaître law'),
      expl:t('Lemetr bu munosabatni 1927-yilda o‘z kengayuvchi koinot modelidan nazariy chiqargan va mavjud ma’lumotlar bo‘yicha H_{0} ni baholagan; Xabbl uni 1929-yilda kuzatuvlarda ko‘rsatgan.','Леметр вывел это соотношение теоретически в 1927 году из своей модели расширяющейся Вселенной и оценил H_{0} по имевшимся данным; Хаббл показал его наблюдениями в 1929 году.','Lemaître derived this relation theoretically in 1927 from his expanding-universe model and estimated H_{0} from the available data; Hubble demonstrated it observationally in 1929.'),
      vars:[ ['v', t('uzoqlashish tezligi','скорость удаления','recession velocity')], ['H_{0}', t('Xabbl doimiysi','постоянная Хаббла','Hubble constant')], ['d', t('masofa','расстояние','distance')] ] }
  ],
